public class Main {
    static boolean isLeap(int year) {
        return (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
    }

    public static void main(String[] args) {
        int[] years = {1900, 2000, 2023, 2024};
        for (int y : years) {
            System.out.println(y + (isLeap(y) ? " is a leap year" : " is not a leap year"));
        }
    }
}
